import { describe, expect, it } from "vitest";
import {
  createSessionHistoryOrigins,
  HISTORY_PREFIX_SCHEMA,
} from "../src/lib/session-history-origins.js";
import {
  messagesToContextItems,
  contextItemsToMessages,
  createSummaryContextItem,
} from "../src/lib/context-memory-kernel/message-adapter.js";

const head = "a".repeat(64);

// Independent regression coverage for the "reject history source tampering"
// behavior of createSessionHistoryOrigins. Origins are only carried forward
// when a compaction summary parent digest resolves to the current session's
// indexed context. A summary item whose ancestry was computed under a
// different session identity must not leak an origin into the display
// history, and a rewind across it must be refused.
describe("history source identity tampering", () => {
  function event(messages, retainedMessageCount) {
    return {
      prevHash: head,
      data: {
        action: "restore-conversation",
        messages: messages.slice(0, retainedMessageCount),
        historyPrefix: {
          schema: HISTORY_PREFIX_SCHEMA,
          sourceHead: head,
          sourceMessageCount: messages.length,
          retainedMessageCount,
        },
      },
    };
  }

  // Build a compact() payload from a summary whose parents are the context
  // items of `source`, and a tail item retained after the summary.
  function compactWithSummary(source, summarySessionId, canonicalSessionId) {
    const contextItems = messagesToContextItems(source, {
      sessionId: summarySessionId,
    });
    const summary = createSummaryContextItem({
      messages: [{ role: "assistant", content: "digest-bound summary" }],
      parents: contextItems.slice(0, 1),
      operationId: "verify09",
      now: "2026-09-27T00:00:00.000Z",
    });
    const outputItems = [summary, contextItems.at(-1)];
    const output = contextItemsToMessages(outputItems);
    return {
      messages: output,
      canonical: { sessionId: canonicalSessionId, outputItems },
    };
  }

  it("carries ancestry for a summary whose parents match the canonical session, so a rewind is allowed", () => {
    const source = [
      { role: "user", content: "first" },
      { role: "assistant", content: "answer" },
    ];
    const origins = createSessionHistoryOrigins();
    origins.appendPersisted(source[0], 0);
    origins.appendPersisted(source[1], 1);
    const payload = compactWithSummary(
      source,
      "session-A",
      "session-A",
    );
    origins.compact(payload);
    // The summary inherits the first user origin {first:0,last:0}; rewinding
    // one retained message back to cutoff 0 is legitimate.
    expect(origins.rewind(event(payload.messages, 1), 2)).toBe(0);
  });

  it("refuses a summary whose parent digests were computed under a different session identity", () => {
    const source = [
      { role: "user", content: "first" },
      { role: "assistant", content: "answer" },
    ];
    const origins = createSessionHistoryOrigins();
    origins.appendPersisted(source[0], 0);
    origins.appendPersisted(source[1], 1);
    // Same messages, but the summary ancestry is bound to session "other";
    // the canonical compact happens under "session-A", so the parent digest
    // does not resolve to the indexed context and the summary origin is null.
    const payload = compactWithSummary(
      source,
      "other",
      "session-A",
    );
    origins.compact(payload);
    expect(origins.rewind(event(payload.messages, 1), 2)).toBeNull();
  });

  it("positive control: a compact summary in the canonical session is fingerprint-verified and readable", () => {
    const source = [
      { role: "user", content: "alpha" },
      { role: "assistant", content: "beta" },
    ];
    const origins = createSessionHistoryOrigins();
    origins.appendPersisted(source[0], 0);
    origins.appendPersisted(source[1], 1);
    const payload = compactWithSummary(
      source,
      "session-B",
      "session-B",
    );
    origins.compact(payload);
    // Cutoff is derived from the summary's spanned first origin (0).
    expect(origins.rewind(event(payload.messages, 1), 2)).toBe(0);
  });

  it("negative control: tampering the retained message content breaks the fingerprint before the rewind", () => {
    const source = [
      { role: "user", content: "alpha" },
      { role: "assistant", content: "beta" },
    ];
    const origins = createSessionHistoryOrigins();
    origins.appendPersisted(source[0], 0);
    origins.appendPersisted(source[1], 1);
    const payload = compactWithSummary(
      source,
      "session-B",
      "session-B",
    );
    origins.compact(payload);
    const tampered = event(payload.messages, 1);
    tampered.data.messages[0] = { role: "user", content: "forged" };
    expect(origins.rewind(tampered, 2)).toBeNull();
  });

  it("negative control: a mismatched prefix sourceHead is refused while the correct head is accepted", () => {
    const source = [
      { role: "user", content: "gamma" },
      { role: "assistant", content: "delta" },
    ];
    const origins = createSessionHistoryOrigins();
    origins.appendPersisted(source[0], 0);
    origins.appendPersisted(source[1], 1);
    const valid = event(source, 1);
    const forged = event(source, 1);
    forged.prevHash = "b".repeat(64);
    forged.data.historyPrefix.sourceHead = "b".repeat(64);
    expect(origins.rewind(forged, 2)).toBeNull();
    expect(origins.rewind(valid, 2)).toBe(0);
  });

  it("negative control: a mismatched sourceMessageCount is refused while the correct count is accepted", () => {
    const source = [
      { role: "user", content: "epsilon" },
      { role: "assistant", content: "zeta" },
    ];
    const origins = createSessionHistoryOrigins();
    origins.appendPersisted(source[0], 0);
    origins.appendPersisted(source[1], 1);
    const valid = event(source, 1);
    const forged = event(source, 1);
    forged.data.historyPrefix.sourceMessageCount = source.length - 1;
    expect(origins.rewind(forged, 2)).toBeNull();
    expect(origins.rewind(valid, 2)).toBe(0);
  });
});

